=== HeadlessClientOptions.cs ===
1: using System.Globalization;
2: 
3: namespace LeikwanBridge.Core.Services;
4: 
5: // Command line surface of the windowless clients (macOS and Windows).
6: //
7: //   LeikwanBridge.Mac --headless --panel <url> --client-id <n> --agent-token-file <path>
8: //                     [--forwards all|1,2] [--log-file <path>] [--status-file <path>]
9: //                     [--once] [--print-status]
10: //
11: // The windowless clients run the exact same managed payload, Core services and
12: // lease/heartbeat code as the windowed applications; only the process lifecycle
13: // differs. That keeps the runtime attestation (fingerprint + self hash), the
14: // update pinning and the failover behaviour identical between both surfaces.
15: public sealed record HeadlessClientOptions
16: {
17:     public const string Flag = "--headless";
18: 
19:     public string PanelUrl { get; init; } = string.Empty;
20:     public int ClientId { get; init; }
21:     public string AgentToken { get; init; } = string.Empty;
22:     public string AgentTokenFile { get; init; } = string.Empty;
23:     public string Forwards { get; init; } = "all";
24:     public string LogFile { get; init; } = string.Empty;
25:     public string StatusFile { get; init; } = string.Empty;
26:     public bool Once { get; init; }
27:     public bool PrintStatus { get; init; }
28:     public TimeSpan OnceWindow { get; init; } = TimeSpan.FromSeconds(75);
29:     public TimeSpan StatusInterval { get; init; } = TimeSpan.FromSeconds(15);
30: 
31:     public static string Usage =>
32:         "usage: <client> --headless [--panel <url>] [--client-id <n>] "
33:         + "[--agent-token <token>|--agent-token-file <path>] [--forwards all|1,2] "
34:         + "[--log-file <path>] [--status-file <path>] [--once] [--print-status]";
35: 
36:     public static bool TryParse(
37:         IReadOnlyList<string> args,
38:         out HeadlessClientOptions options,
39:         out string error)
40:     {
41:         options = new HeadlessClientOptions();
42:         error = string.Empty;
43:         string panel = string.Empty;
44:         string token = string.Empty;
45:         string tokenFile = string.Empty;
46:         string forwards = "all";
47:         string logFile = string.Empty;
48:         string statusFile = string.Empty;
49:         var once = false;
50:         var printStatus = false;
51:         var onceWindow = TimeSpan.FromSeconds(75);
52:         var statusInterval = TimeSpan.FromSeconds(15);
53:         var clientId = 0;
54: 
55:         for (var index = 0; index < args.Count; index++)
56:         {
57:             var argument = args[index];
58:             if (string.Equals(argument, Flag, StringComparison.Ordinal))
59:                 continue;
60:             switch (argument)
61:             {
62:                 case "--panel":
63:                     if (!TryRead(args, ref index, out panel))
64:                         return Fail(out options, out error, "--panel requires a value");
65:                     break;
66:                 case "--client-id":
67:                     if (!TryRead(args, ref index, out var rawClientId)
68:                         || !int.TryParse(rawClientId, NumberStyles.Integer, CultureInfo.InvariantCulture, out clientId)
69:                         || clientId <= 0)
70:                         return Fail(out options, out error, "--client-id requires a positive integer");
71:                     break;
72:                 case "--agent-token":
73:                     if (!TryRead(args, ref index, out token))
74:                         return Fail(out options, out error, "--agent-token requires a value");
75:                     break;
76:                 case "--agent-token-file":
77:                     if (!TryRead(args, ref index, out tokenFile))
78:                         return Fail(out options, out error, "--agent-token-file requires a value");
79:                     break;
80:                 case "--forwards":
81:                     if (!TryRead(args, ref index, out forwards) || string.IsNullOrWhiteSpace(forwards))
82:                         return Fail(out options, out error, "--forwards requires a value");
83:                     break;
84:                 case "--log-file":
85:                     if (!TryRead(args, ref index, out logFile))
86:                         return Fail(out options, out error, "--log-file requires a value");
87:                     break;
88:                 case "--status-file":
89:                     if (!TryRead(args, ref index, out statusFile))
90:                         return Fail(out options, out error, "--status-file requires a value");
91:                     break;
92:                 case "--once":
93:                     once = true;
94:                     break;
95:                 case "--print-status":
96:                     printStatus = true;
97:                     break;
98:                 case "--once-window":
99:                     if (!TryRead(args, ref index, out var rawOnceWindow)
100:                         || !int.TryParse(rawOnceWindow, NumberStyles.Integer, CultureInfo.InvariantCulture, out var onceSeconds)
101:                         || onceSeconds is < 5 or > 900)
102:                         return Fail(out options, out error, "--once-window requires 5..900 seconds");
103:                     onceWindow = TimeSpan.FromSeconds(onceSeconds);
104:                     break;
105:                 case "--status-interval":
106:                     if (!TryRead(args, ref index, out var rawStatusInterval)
107:                         || !int.TryParse(rawStatusInterval, NumberStyles.Integer, CultureInfo.InvariantCulture, out var statusSeconds)
108:                         || statusSeconds is < 5 or > 600)
109:                         return Fail(out options, out error, "--status-interval requires 5..600 seconds");
110:                     statusInterval = TimeSpan.FromSeconds(statusSeconds);
111:                     break;
112:                 default:
113:                     return Fail(out options, out error, $"unknown argument: {argument}");
114:             }
115:         }
116: 
117:         if (string.IsNullOrWhiteSpace(token) && !string.IsNullOrWhiteSpace(tokenFile))
118:         {
119:             try
120:             {
121:                 token = File.ReadAllText(tokenFile).Trim();
122:             }
123:             catch (Exception exception) when (exception is IOException or UnauthorizedAccessException)
124:             {
125:                 return Fail(out options, out error, $"agent token file could not be read: {exception.GetType().Name}");
126:             }
127:         }
128: 
129:         if (clientId <= 0 && string.IsNullOrWhiteSpace(token))
130:             return Fail(out options, out error, "either --client-id with an agent token, or a previously signed-in config, is required");
131: 
132:         if (string.IsNullOrWhiteSpace(token) && !string.IsNullOrWhiteSpace(tokenFile))
133:             return Fail(out options, out error, "agent token file is empty");
134: 
135:         if (!string.IsNullOrWhiteSpace(panel)
136:             && !panel.StartsWith("http://", StringComparison.OrdinalIgnoreCase)
137:             && !panel.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
138:             return Fail(out options, out error, "--panel must be an absolute http(s) URL");
139: 
140:         if (!string.IsNullOrWhiteSpace(logFile) && !Path.IsPathFullyQualified(logFile))
141:             return Fail(out options, out error, "--log-file must be an absolute path");
142:         if (!string.IsNullOrWhiteSpace(statusFile) && !Path.IsPathFullyQualified(statusFile))
143:             return Fail(out options, out error, "--status-file must be an absolute path");
144: 
145:         options = new HeadlessClientOptions
146:         {
147:             PanelUrl = panel.Trim().TrimEnd('/'),
148:             ClientId = clientId,
149:             AgentToken = token.Trim(),
150:             AgentTokenFile = tokenFile.Trim(),
151:             Forwards = forwards.Trim(),
152:             LogFile = logFile.Trim(),
153:             StatusFile = statusFile.Trim(),
154:             Once = once,
155:             PrintStatus = printStatus,
156:             OnceWindow = onceWindow,
157:             StatusInterval = statusInterval,
158:         };
159:         return true;
160:     }
161: 
162:     public static IReadOnlyList<int> ParseForwardSelection(string value)
163:     {
164:         if (string.IsNullOrWhiteSpace(value)
165:             || string.Equals(value.Trim(), "all", StringComparison.OrdinalIgnoreCase))
166:             return [];
167:         var result = new List<int>();
168:         foreach (var part in value.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
169:         {
170:             if (!int.TryParse(part, NumberStyles.Integer, CultureInfo.InvariantCulture, out var id) || id <= 0)
171:                 throw new InvalidOperationException($"invalid forward id: {part}");
172:             if (!result.Contains(id))
173:                 result.Add(id);
174:         }
175:         return result;
176:     }
177: 
178:     private static bool TryRead(IReadOnlyList<string> args, ref int index, out string value)
179:     {
180:         if (index + 1 >= args.Count)
181:         {
182:             value = string.Empty;
183:             return false;
184:         }
185: 
186:         index++;
187:         value = args[index];
188:         return true;
189:     }
190: 
191:     private static bool Fail(out HeadlessClientOptions options, out string error, string message)
192:     {
193:         options = new HeadlessClientOptions();
194:         error = message;
195:         return false;
196:     }
197: }
198: // The windowless clients publish the same status document so a supervisor
199: // (launchd, the Windows SCM, or an operator) can read one shape on both
200: // platforms.
201: public sealed record HeadlessClientForward(
202:     int ForwardId,
203:     string Name,
204:     string Mode,
205:     int ListenPort,
206:     bool Running,
207:     string Status);
208: 
209: public sealed record HeadlessClientStatus(
210:     string Version,
211:     bool Connected,
212:     string ConnectionStatus,
213:     string LastErrorCode,
214:     string ClientName,
215:     IReadOnlyList<HeadlessClientForward> Forwards,
216:     DateTimeOffset UpdatedAt);
217: 
218: [System.Text.Json.Serialization.JsonSerializable(typeof(HeadlessClientStatus))]
219: public sealed partial class HeadlessClientStatusContext : System.Text.Json.Serialization.JsonSerializerContext
220: {
221: }

